for(const [parent,id,text] of [['mapEditorMenu','battleEditorMenu','▦ สร้างฉากต่อสู้แบบกริด'],['gameMapEdit','battleGameMenu','▦ ฉากต่อสู้ / ทดลองเดิน']]){const b=document.createElement('button');b.id=id;b.textContent=text;$(parent).insertAdjacentElement('afterend',b);b.onclick=()=>{returnTo=screen;show('battleEditorScreen');};}
