const brushes=[['select','⌖ เลือกช่อง'],['pan','✋ เลื่อนฉาก'],['grass','🌱 หญ้า'],['ground','▧ พื้นดิน'],['bush','🌿 พุ่มหญ้า'],['tree','🌳 ต้นไม้'],['rock','🪨 ก้อนหิน'],['wall','▥ ผนัง'],['tent','⛺ เต็นท์'],['chest','🧰 กล่องสมบัติ'],['campfire','🔥 กองไฟ'],['crate','📦 ลังไม้'],['barrel','🛢 ถังไม้'],['sign','🪧 ป้ายทาง'],['stump','🪵 ตอไม้'],['log','🪵 ขอนไม้'],['fern','🌿 เฟิร์น'],['mushroom','🍄 เห็ดถ้ำ'],['stalagmite','⛰ หินงอก'],['crystal','💎 ผลึกแร่'],['water','≈ น้ำ'],['raise','▴ ยกพื้น'],['lower','▾ ลดพื้น'],['climb','↟ ทางปีน'],['player','🔵 จุดผู้เล่น'],['enemy','🔴 จุดมอนสเตอร์'],['noSpawn','× ลบจุดเกิด'],['erase','⌫ ล้างช่อง']];
